@rule
def advance(phase):
    if phase < 343:
        phase = phase + 1


@system
def BitPrimitivePipelineSystem():  # noqa: N802
    phase: bits[16] = 0
    frame = stimulus(phase)
    packet = Item(
        value=frame.input_value,
        priority_index=frame.input_priority_index,
        high_index=frame.input_high_index,
        priority_valid=frame.input_priority_valid,
        onehot_conflict=frame.input_onehot_conflict,
        population=frame.input_population,
        leading=frame.input_leading,
        trailing=frame.input_trailing,
    )
    dut = BitPrimitivePipeline(frame.valid, packet, frame.take)

    @rule
    def check():
        assert (
            dut.ready == frame.expected_ready
        ), "bit_primitive_pipeline input capacity"
        assert (
            dut.valid == frame.expected_valid
        ), "bit_primitive_pipeline result availability"
        assert (
            dut.data.value == frame.expected_data_value
        ), "bit_primitive_pipeline value old-state check"
        assert (
            dut.data.priority_index == frame.expected_data_priority_index
        ), "bit_primitive_pipeline priority_index old-state check"
        assert (
            dut.data.high_index == frame.expected_data_high_index
        ), "bit_primitive_pipeline high_index old-state check"
        assert (
            dut.data.priority_valid == frame.expected_data_priority_valid
        ), "bit_primitive_pipeline priority_valid old-state check"
        assert (
            dut.data.onehot_conflict == frame.expected_data_onehot_conflict
        ), "bit_primitive_pipeline onehot_conflict old-state check"
        assert (
            dut.data.population == frame.expected_data_population
        ), "bit_primitive_pipeline population old-state check"
        assert (
            dut.data.leading == frame.expected_data_leading
        ), "bit_primitive_pipeline leading old-state check"
        assert (
            dut.data.trailing == frame.expected_data_trailing
        ), "bit_primitive_pipeline trailing old-state check"
        log("info", "phase", phase)
        log("info", "ready", dut.ready)
        log("info", "valid", dut.valid)
        log("info", "value", dut.data.value)
        log("info", "priority_index", dut.data.priority_index)
        log("info", "high_index", dut.data.high_index)
        log("info", "priority_valid", dut.data.priority_valid)
        log("info", "onehot_conflict", dut.data.onehot_conflict)
        log("info", "population", dut.data.population)
        log("info", "leading", dut.data.leading)
        log("info", "trailing", dut.data.trailing)

    advance(phase)
    check()
